<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { addresses, addAddress, updateAddress, deleteAddress, setDefaultAddress } from '../../api/user'
import PageTitle from '../../components/PageTitle.vue'
const rows=ref([]),loading=ref(false),dialog=ref(false),editId=ref(null),formRef=ref(),form=reactive({receiverName:'',receiverPhone:'',province:'',city:'',district:'',detailAddress:'',isDefault:0});const rules={receiverName:[{required:true,message:'请输入收件人',trigger:'blur'},{min:2,max:20,message:'姓名长度2-20位'}],receiverPhone:[{required:true,message:'请输入手机号'},{pattern:/^1[3-9]\d{9}$/,message:'手机号格式不正确'}],province:[{required:true,message:'请输入省份'}],city:[{required:true,message:'请输入城市'}],district:[{required:true,message:'请输入区县'}],detailAddress:[{required:true,message:'请输入详细地址'},{min:5,max:100,message:'地址长度5-100位'}]}
async function load(){loading.value=true;try{rows.value=await addresses()||[]}finally{loading.value=false}}
function open(row){editId.value=row?.id||null;Object.assign(form,row?{...row}:{receiverName:'',receiverPhone:'',province:'',city:'',district:'',detailAddress:'',isDefault:0});dialog.value=true}
async function save(){await formRef.value.validate();if(editId.value)await updateAddress(editId.value,form);else await addAddress(form);dialog.value=false;ElMessage.success('地址已保存');load()}
async function remove(row){await ElMessageBox.confirm('确认删除该收货地址？');await deleteAddress(row.id);ElMessage.success('地址已删除');load()}
async function makeDefault(row){await setDefaultAddress(row.id);ElMessage.success('默认地址已更新');load()}
onMounted(load)
</script>
<template><PageTitle eyebrow="DELIVERY" title="收货地址"/><div class="toolbar"><el-button type="primary" @click="open()">新增地址</el-button></div><div v-loading="loading" class="album-grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))"><article v-for="row in rows" :key="row.id" class="content-card"><div class="section-head"><b>{{row.receiverName}}</b><el-tag v-if="Number(row.isDefault)===1" type="success">默认</el-tag></div><p>{{row.receiverPhone}}</p><p class="muted">{{row.fullAddress||`${row.province} ${row.city} ${row.district} ${row.detailAddress}`}}</p><div class="actions"><el-button v-if="Number(row.isDefault)!==1" text @click="makeDefault(row)">设为默认</el-button><el-button text @click="open(row)">编辑</el-button><el-button type="danger" text @click="remove(row)">删除</el-button></div></article><el-empty v-if="!loading&&!rows.length" description="还没有收货地址"/></div><el-dialog v-model="dialog" :title="editId?'编辑地址':'新增地址'" width="min(600px,92vw)"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="收件人" prop="receiverName"><el-input v-model="form.receiverName"/></el-form-item><el-form-item label="手机号" prop="receiverPhone"><el-input v-model="form.receiverPhone"/></el-form-item><el-form-item label="省份" prop="province"><el-input v-model="form.province"/></el-form-item><el-form-item label="城市" prop="city"><el-input v-model="form.city"/></el-form-item><el-form-item label="区县" prop="district"><el-input v-model="form.district"/></el-form-item><el-form-item label="详细地址" prop="detailAddress" class="span-2"><el-input v-model="form.detailAddress"/></el-form-item></div><el-checkbox v-model="form.isDefault" :true-value="1" :false-value="0">设为默认地址</el-checkbox></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
